    private void jButton6ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton6ActionPerformed
    String kode = getKodeTerpilih();
        String nama = jTextField10.getText().trim();
        String strHarga = jTextField11.getText().trim();
        String strQty = jTextField12.getText().trim();

        if (kode.isEmpty() || nama.isEmpty() || strHarga.isEmpty()) {
            javax.swing.JOptionPane.showMessageDialog(this, "Pilih Kode Produk terlebih dahulu!");
            return;
        }

        int qty;
        try {
            qty = Integer.parseInt(strQty);
            if (qty <= 0) throw new NumberFormatException();
        } catch (NumberFormatException e) {
            javax.swing.JOptionPane.showMessageDialog(this, "Jumlah (Qty) harus berupa angka lebih dari 0!");
            return;
        }

        // Cek ketersediaan stok di database
        int stokTersedia = 0;
        for (ProdukToko p : DataStore.daftarProduk) {
            if (p.getIdProduk().equalsIgnoreCase(kode)) {
                stokTersedia = p.getStok();
                break;
            }
        }

        javax.swing.table.DefaultTableModel model = (javax.swing.table.DefaultTableModel) jTable1.getModel();
        int qtyDiKeranjang = 0;
        int barisSama = -1;
        for (int i = 0; i < model.getRowCount(); i++) {
            if (model.getValueAt(i, 0).toString().equalsIgnoreCase(kode)) {
                qtyDiKeranjang = Integer.parseInt(model.getValueAt(i, 3).toString());
                barisSama = i;
                break;
            }
        }

        if (qty + qtyDiKeranjang > stokTersedia) {
            javax.swing.JOptionPane.showMessageDialog(this, "Stok tidak mencukupi! Sisa stok: " + stokTersedia);
            return;
        }

        int harga = (int) DataStore.parseRupiah(strHarga);
        if (barisSama != -1) {
            int qtyBaru = qtyDiKeranjang + qty;
            model.setValueAt(qtyBaru, barisSama, 3);
            model.setValueAt(DataStore.formatRupiah(harga * qtyBaru), barisSama, 4);
        } else {
            model.addRow(new Object[]{kode.toUpperCase(), nama, DataStore.formatRupiah(harga), qty, DataStore.formatRupiah(harga * qty)});
        }

        hitungTotalKeranjang();
        jComboBox1.setSelectedIndex(0);
        jTextField10.setText("");
        jTextField11.setText("");
        jTextField12.setText("");
        jComboBox1.requestFocus();   // TODO add your handling code here:
    }//GEN-LAST:event_jButton6ActionPerformed

    private void jButton7ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton7ActionPerformed
    if (!"admin".equalsIgnoreCase(DataStore.currentRole)) {
            javax.swing.JOptionPane.showMessageDialog(this, "Akses ditolak! Hanya Admin yang dapat menghapus item.");
            return;
        }

        int baris = jTable1.getSelectedRow();
        if (baris == -1) {
            javax.swing.JOptionPane.showMessageDialog(this, "Pilih baris item di keranjang yang ingin dihapus!");
            return;
        }

        javax.swing.table.DefaultTableModel model = (javax.swing.table.DefaultTableModel) jTable1.getModel();
        model.removeRow(baris);
        hitungTotalKeranjang();    // TODO add your handling code here:
    }//GEN-LAST:event_jButton7ActionPerformed

    private void jButton8ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton8ActionPerformed
        javax.swing.table.DefaultTableModel model = (javax.swing.table.DefaultTableModel) jTable1.getModel();
        if (model.getRowCount() == 0) {
            javax.swing.JOptionPane.showMessageDialog(this, "Keranjang belanja masih kosong!");
            return;
        }

        double tunai;
        try {
            tunai = DataStore.parseRupiah(jTextField14.getText());
            if (tunai <= 0) throw new NumberFormatException();
        } catch (NumberFormatException e) {
            javax.swing.JOptionPane.showMessageDialog(this, "Masukkan nominal pembayaran Tunai yang valid!");
            return;
        }

        if (tunai < totalBelanja) {
            javax.swing.JOptionPane.showMessageDialog(this, 
                "Uang tunai kurang dari Total Bayar!\n"
                + "Total Bayar : " + DataStore.formatRupiah(totalBelanja) + "\n"
                + "Tunai Anda  : " + DataStore.formatRupiah(tunai));
            return;
        }

        String baseId = jTextField6.getText().trim();
        String tgl = jTextField7.getText().trim();
        String pelanggan = jTextField8.getText().trim();
        String kasir = DataStore.currentUser.isEmpty() ? "Admin" : DataStore.currentUser;
        boolean semuaBerhasil = true;

        // Instansiasi objek OOP PenjualanToko (Inheritance dari Penjualan JAR dosen)
        Pelanggan plgObj = new Pelanggan("PLG-UMUM", pelanggan, "-", "-", "Umum");
        PenjualanToko trxOop = new PenjualanToko(baseId, plgObj, kasir);
        trxOop.setTunai(tunai);

        // Susun rincian item untuk tampilan struk kasir
        StringBuilder daftarStruk = new StringBuilder();
        for (int i = 0; i < model.getRowCount(); i++) {
            String kodeProduk = model.getValueAt(i, 0).toString();
            String namaItem = model.getValueAt(i, 1).toString();
            String hargaStr = model.getValueAt(i, 2).toString();
            int qty = Integer.parseInt(model.getValueAt(i, 3).toString());
            double subtotal = DataStore.parseRupiah(model.getValueAt(i, 4).toString());

            // Masukkan item ke objek PenjualanToko
            for (ProdukToko p : DataStore.daftarProduk) {
                if (p.getIdProduk().equalsIgnoreCase(kodeProduk)) {
                    ProdukToko itemSementara = new ProdukToko(
                        p.getIdProduk(), p.getNamaProduk(), p.getKategori(),
                        p.getHargaBeli().doubleValue(), p.getHargaJual().doubleValue(), p.getStok()
                    );
                    trxOop.tambahPenjualan(itemSementara, qty, kasir, "Penjualan Kasir");
                    break;
                }
            }

            daftarStruk.append(String.format("%-18s\n  %d x %s = %s\n", 
                namaItem, qty, hargaStr, DataStore.formatRupiah(subtotal)));

            String idUnik = (model.getRowCount() == 1) ? baseId : baseId + "-" + (i + 1);
            if (!DataStore.prosesTransaksi(idUnik, "PENJUALAN", kodeProduk, namaItem, qty, subtotal)) {
                semuaBerhasil = false;
                break;
            }
        }

        if (semuaBerhasil) {
            trxOop.finalisasiTransaksi(kasir);
            trxOop.cetakNota(); // Mencetak nota ke console NetBeans sebagai bukti OOP
            double kembalian = trxOop.hitungKembalian().doubleValue();

            // Susun tampilan Struk Kasir
            String isiStruk = 
                  "========================================\n"
                + "             TECHSTORE POS              \n"
                + "        Struk Pembayaran Kasir          \n"
                + "========================================\n"
                + "No. Trx   : " + baseId + "\n"
                + "Tanggal   : " + tgl + "\n"
                + "Kasir     : " + kasir + "\n"
                + "Pelanggan : " + pelanggan + "\n"
                + "----------------------------------------\n"
                + daftarStruk.toString()
                + "----------------------------------------\n"
                + "TOTAL     : " + DataStore.formatRupiah(totalBelanja) + "\n"
                + "TUNAI     : " + DataStore.formatRupiah(tunai) + "\n"
                + "KEMBALIAN : " + DataStore.formatRupiah(kembalian) + "\n"
                + "========================================\n"
                + "    Terima Kasih Telah Berbelanja!      \n";

            javax.swing.JTextArea areaStruk = new javax.swing.JTextArea(isiStruk);
            areaStruk.setFont(new java.awt.Font("Monospaced", java.awt.Font.PLAIN, 12));
            areaStruk.setEditable(false);
            areaStruk.setBackground(new java.awt.Color(255, 255, 255));

            Object[] pilihan = {"Cetak Struk", "Tutup"};
            int respon = javax.swing.JOptionPane.showOptionDialog(
                this,
                new javax.swing.JScrollPane(areaStruk),
                "Struk Pembayaran - " + baseId,
                javax.swing.JOptionPane.YES_NO_OPTION,
                javax.swing.JOptionPane.PLAIN_MESSAGE,
                null,
                pilihan,
                pilihan[0]
            );

            // Jika kasir menekan tombol "Cetak Struk"
            if (respon == 0) {
                try {
                    boolean selesai = areaStruk.print();
                    if (selesai) {
                        javax.swing.JOptionPane.showMessageDialog(this, "Struk berhasil dikirim ke printer!");
                    }
                } catch (java.awt.print.PrinterException e) {
                    javax.swing.JOptionPane.showMessageDialog(this, "Gagal mencetak struk: " + e.getMessage(), "Error Cetak", javax.swing.JOptionPane.ERROR_MESSAGE);
                }
            }

            model.setRowCount(0);
            siapkanTransaksiBaru();
        }  // TODO add your handling code here:
    }//GEN-LAST:event_jButton8ActionPerformed


